-- Gold Query
SELECT DISTINCT t1.player_name FROM Player AS t1 INNER JOIN Player_Attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t2.finishing = 1 ORDER BY t1.birthday ASC, t1.player_name NULLS LAST LIMIT 1;

/*
Gold Result:
('Amy Hernandez',)
*/

-- Prediction Query
SELECT "player"."player_name" FROM "player" INNER JOIN "player_attributes" ON "player"."player_api_id" = "player_attributes"."player_api_id" WHERE "player_attributes"."finishing" = 1 ORDER BY "player"."birthday" ASC, player.id NULLS LAST, player_attributes.id NULLS LAST LIMIT 1;

